"""Custom activity dataset for SecondHalf.

Schema (one dict per activity, written out to data/activities.csv):
  id                 -- str, e.g. "ACT001", zero-padded sequential identifier
  title              -- str, short activity name
  description        -- str, 1-2 sentence summary
  category           -- str, one of: learn, create, connect, contribute,
                         physical_outdoor, hobbies, family, memory,
                         practical_useful, mindfulness_reflection
  subcategory        -- str, free-form specific label within the category
  duration_minutes   -- int, realistic time estimate (15-90)
  energy_level       -- str, one of: low, medium, high
  location            -- str, one of: home, outdoor, neighborhood, community
  required_materials -- str, comma-separated list or "none"
  skill_level        -- str, one of: easy, moderate, advanced
  interests          -- list[str], lowercase interest tags for matching
  age_suitability    -- str, usually "senior" or "all_ages"
  purpose            -- list[str], from: connection, contribution, learning,
                         creativity, physical_health, mental_wellbeing,
                         nostalgia, mastery, service
  instructions       -- list[str], 3-6 concrete numbered steps
  safety_notes       -- str, may be ""
  tags               -- list[str], free-form search tags

Run this file directly to write data/activities.csv (list-typed fields are
JSON-encoded into their CSV cell so they round-trip with json.loads()).
"""
import csv
import json
import os

ACTIVITIES = []


def add(**kw):
    ACTIVITIES.append(kw)


