def write_csv():
    out_path = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), "data", "activities.csv")
    fieldnames = [
        "id", "title", "description", "category", "subcategory",
        "duration_minutes", "energy_level", "location", "required_materials",
        "skill_level", "interests", "age_suitability", "purpose",
        "instructions", "safety_notes", "tags",
    ]
    list_fields = {"interests", "purpose", "instructions", "tags"}
    with open(out_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for activity in ACTIVITIES:
            row = dict(activity)
            for field in list_fields:
                row[field] = json.dumps(row[field])
            writer.writerow(row)
    return out_path, len(ACTIVITIES)


if __name__ == "__main__":
    path, count = write_csv()
    print(f"Wrote {count} activities to {path}")

    from collections import Counter
    cat_counts = Counter(a["category"] for a in ACTIVITIES)
    for cat, n in sorted(cat_counts.items()):
        print(f"  {cat}: {n}")
